{
  "headline": "FDA's records trace our supply to a plant classified OAI 275 days before the posting",
  "headline_cites": ["D6"],
  "sentences": [
    {
      "text": "FDA first posted the rifampin injection shortage on 2021-02-17 and it remains Current as of 2026-10-21.",
      "cites": ["E19", "E16"]
    },
    {
      "text": "The shortage listing covers Fresenius Kabi USA, LLC (NDC 63323-351-20), Mylan Institutional (NDC 67457-445-60), and Sanofi-Aventis U.S. LLC (NDC 0068-0597-01).",
      "cites": ["E16", "E17", "E18"]
    },
    {
      "text": "Our Corvale sites hold the Mylan-labeled 600 mg/10 mL vials (NDC 67457-445-60) manufactured by OneSource Specialty Pharma Limited in Bengaluru.",
      "cites": ["E2", "E4", "E5", "E15"]
    },
    {
      "text": "FDA inspected Fresenius Kabi USA, LLC (FEI 1450022) on 2020-05-18 and classified it OAI, 275 days before the shortage posting.",
      "cites": ["D6", "E11"]
    },
    {
      "text": "A later Fresenius inspection on 2022-06-30 was also classified OAI, and a 2023-08-24 inspection was classified VAI.",
      "cites": ["D7", "D10", "E12", "E13"]
    },
    {
      "text": "The highest-ranked mitigation is to transfer 17 vials of 600 mg/10 mL from Corvale Lakeside to Corvale East, raising East from 4.4 to 10 days on hand while Lakeside retains 14 days.",
      "cites": ["D12", "D1", "D3"]
    }
  ]
}
